module barrel_shifter(
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);
    // Internal wires for connecting mux2X1 instances
    wire [7:0] interm_result_1, interm_result_2, interm_result_3;
    // Mux2X1 instances for each stage
    assign interm_result_1 = ctrl[2] ? ({in[3:0], in[7:4]} ) : in ;
    assign interm_result_2 = ctrl[1] ? ({interm_result_1[5:0], interm_result_1[7:6]} ) : interm_result_1 ;
    assign interm_result_3 = ctrl[0] ? ({interm_result_2[6:0], interm_result_2[7]} ) : interm_result_2 ;
    // Final output
    assign out = interm_result_3;
endmodule
